function ch_to_val(ch, first) {
    if (ch === 'a') return first ? 1 : -1;
    if (ch === 'b') return first ? -1 : 1;
    return 0;
}

function hash(sum, R) {
    let h = sum;
    for (let i = 0; i < R.length; i++) {
        h = h * 2 + (R[i] ? 1 : 0);
    }
    return h;
}

function f(sum, R, first) {
    const key = hash(sum, R);
    if (F.has(key)) return F.get(key);
    if (sum === 2 * (n - 1)) return 0;

    let ans = -1000;
    const ns = sum + 1;
    const CH = new Array(ns + 1).fill(null);

    for (let r = 0; r <= ns; r++) {
        const can_see = (r < R.length && R[r]) || (r - 1 >= 0 && R[r - 1]);
        if (!can_see) continue;
        const c = ns - r;
        if (c < 0 || c >= n || r < 0 || r >= n) continue;
        CH[r] = G[r][c];
    }

    for (let r = 0; r <= ns; r++) {
        if (CH[r] !== null) {
            const ch = CH[r];
            const NR = new Array(ns + 1).fill(false);
            for (let rr = 0; rr <= ns; rr++) {
                if (CH[rr] !== null && CH[rr] === ch) {
                    NR[rr] = true;
                    CH[rr] = null;
                }
            }
            const val = ch_to_val(ch, first) - f(ns, NR, !first);
            if (val > ans) ans = val;
        }
    }

    F.set(key, ans);
    return ans;
