        G.push(input[i + 1].split(''));
    }

    const initialR = [true];
    const ans = ch_to_val(G[0][0], true) - f(0, initialR, false);

    if (ans > 0) console.log("FIRST");
    else if (ans < 0) console.log("SECOND");
    else console.log("DRAW");
}

main();

